    tolerance: 0.000001;
    max_iterations: 1000;

    iteration: 0;

    while[iteration < max_iterations;
        mid: (low + high) % 2.0;

        val: 0.0;
        power: 0;

        i: 0;

        while[i < n;
            val: val + (x[i]) * (mid xexp power);
            power: power + 1;
            i: i + 1;
        ];

        if[abs[val] < tolerance;
            : mid;
        ];

        if[((val * x[n - 1]) > 0);
            high: mid;
            ];

        if[((val * x[n - 1]) < 0);
            low: mid;
            ];

        if[not ((low + tolerance) >= high);
            iteration: iteration + 1;
            ];

        if[((low + tolerance) >= high);
            : mid;
            ];
        ];

    : 0.0;
    };
